// supabase/functions/decline-call/index.ts
//
// Called directly from native Android code (see
// android/app/src/main/java/com/nextgen/app/CallActionReceiver.java) the
// moment someone taps "Decline" on the incoming-call system notification.
// At that point the app process may not even be running, so there is no
// Supabase session/JWT available on-device to authenticate a normal
// request — the WebView's session lives in the WebView's own storage,
// which native code can't reach.
//
// Deliberately accepts just `callId` with no user JWT. callId is a
// crypto.randomUUID() generated by the caller and known only to the
// caller and callee for this one call — an unguessable bearer credential,
// same trust model as a password-reset link token. The worst a leaked
// callId enables is declining one already-placed call, so this is an
// intentional, scoped exception to requiring auth, not an oversight.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;

const supabaseAdmin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};
const jsonHeaders = { ...corsHeaders, 'Content-Type': 'application/json' };

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }
  if (req.method !== 'POST') {
    return new Response('method not allowed', { status: 405, headers: corsHeaders });
  }

  try {
    const { callId } = await req.json();
    if (!callId || typeof callId !== 'string') {
      return new Response(JSON.stringify({ error: 'callId is required' }), { status: 400, headers: jsonHeaders });
    }

    const { data: invite, error: fetchErr } = await supabaseAdmin
      .from('call_invites')
      .select('call_id, caller_id, callee_id, call_type, status')
      .eq('call_id', callId)
      .maybeSingle();
    if (fetchErr || !invite) {
      return new Response(JSON.stringify({ error: 'call not found' }), { status: 404, headers: jsonHeaders });
    }
    if (invite.status !== 'ringing') {
      // Already answered, cancelled, or declined some other way (e.g. the
      // in-app banner) — nothing to do, and not an error.
      return new Response(JSON.stringify({ ok: true, alreadyResolved: true }), { headers: jsonHeaders });
    }

    await supabaseAdmin.from('call_invites').update({ status: 'declined' }).eq('call_id', callId);

    await supabaseAdmin.from('calls').insert({
      caller_id: invite.caller_id,
      callee_id: invite.callee_id,
      status: 'declined',
      duration_seconds: 0,
      call_type: invite.call_type,
    });

    // Tell the caller's already-open call screen right away — mirrors
    // what CallContext.tsx's own in-app decline() does.
    const channel = supabaseAdmin.channel(`call:${callId}`, { config: { private: true } });
    await new Promise<void>((resolve) => {
      const timeout = setTimeout(resolve, 3000);
      channel.subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          clearTimeout(timeout);
          channel.send({ type: 'broadcast', event: 'decline', payload: {} }).finally(() => resolve());
        } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
          clearTimeout(timeout);
          resolve();
        }
      });
    });
    setTimeout(() => supabaseAdmin.removeChannel(channel), 1000);

    return new Response(JSON.stringify({ ok: true }), { headers: jsonHeaders });
  } catch (e) {
    console.error('decline-call error', e);
    return new Response(JSON.stringify({ error: (e as Error).message }), { status: 500, headers: jsonHeaders });
  }
});
